// CostEstimator page component
import React, { useState } from "react";
import "../styles/cost.css";

function CostEstimator() {

  const [caseType, setCaseType] = useState("");
  const [complexity, setComplexity] = useState("");
  const [result, setResult] = useState("");

  const calculateCost = () => {

    let cost = 0;

    if (caseType === "Family") cost += 5000;
    if (caseType === "Criminal") cost += 8000;
    if (caseType === "Property") cost += 6000;

    if (complexity === "Low") cost += 1000;
    if (complexity === "Medium") cost += 2000;
    if (complexity === "High") cost += 4000;

    setResult("Estimated Cost: Rs. " + cost);

  };

  return (
    <div className="cost-container">

      <h1>Legal Cost Estimator</h1>

      <div className="cost-form">

        <label>Select Case Type</label>

        <select
          value={caseType}
          onChange={(e) => setCaseType(e.target.value)}
        >
          <option value="">-- Select Case --</option>
          <option value="Family">Family Case</option>
          <option value="Criminal">Criminal Case</option>
          <option value="Property">Property Case</option>
        </select>

        <label>Case Complexity</label>

        <select
          value={complexity}
          onChange={(e) => setComplexity(e.target.value)}
        >
          <option value="">-- Select Complexity --</option>
          <option value="Low">Low</option>
          <option value="Medium">Medium</option>
          <option value="High">High</option>
        </select>

        <button onClick={calculateCost}>
          Calculate Cost
        </button>

        {result && (
          <h2 className="result">
            {result}
          </h2>
        )}

      </div>

    </div>
  );
}

export default CostEstimator;
